"use client"

import React, { useState } from 'react';

const DashboardPage = () => {
  const [totalAmount, setTotalAmount] = useState<number | null>(null);

  const handleApplyLoan = async () => {
    const response = await fetch('/api/invoices/total');
    const data = await response.json();
    setTotalAmount(data.total);
  };

  return (
    <div>
      <h1>Dashboard</h1>
      <button 
        onClick={handleApplyLoan} 
        className="mt-4 rounded-lg bg-green-500 px-4 py-2 text-white hover:bg-green-400"
      >
        Apply Loan
      </button>
      {totalAmount !== null && (
        <div className="mt-4">
          <h2>Total Amount: ${totalAmount}</h2>
          <button 
            onClick={() => window.print()} 
            className="mt-4 rounded-lg bg-blue-500 px-4 py-2 text-white hover:bg-blue-400"
          >
            Print Receipt
          </button>
        </div>
      )}
    </div>
  );
};

export default DashboardPage;